export function validateConfig(
  value: Config | ConfigInput,
  provider = "",
  operation = "create",
): void {
  const message = create(
    ConfigSchema,
    value as MessageInitShape<typeof ConfigSchema>,
  );
  const result = configValidator.validate(ConfigSchema, message);
  if (result.kind === "error") {
    throw sandboxError(
      {
        kind: ErrorKind.InvalidArgument,
        provider,
        operation,
        field: "",
        message: "sandbox-kit: invalid configuration",
      },
      result.error,
    );
  }
  if (result.kind === "invalid") {
    const violation = result.violations[0]!;
    const ruleID = violation.ruleId;
    let field = pathToString(violation.field);
    const rule = stableRuleIDs[ruleID] ?? ruleID;
    if (!field) {
      field = messageFieldHint(ruleID);
    }
    validationError(
      provider,
      operation,
      field,
      rule,
      violation.message || "invalid configuration",
    );
  }
  if (message.endpoint !== undefined && !validSecureEndpoint(message.endpoint)) {
    validationError(
      provider,
      operation,
      "endpoint",
      "secure_endpoint",
      "must use HTTPS except for loopback HTTP development endpoints",
    );
  }
}

